contract ReentrantDepositor {
    C c;
    bool ok;
    constructor(C _c) { c = _c; }
    function deposit(uint256 a) external payable { c.addToBalance{value: a}(); }
    function withdraw() external {
        (bool s, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        ok = s;
    }
    receive() external payable {
        // benign re-entrancy: try to withdraw again; in C the balance is already 0 so this succeeds
        c.withdrawBalance();
    }
    function lastOk() external view returns (bool) { return ok; }
}

