        c.addToBalance{value: amount}();

        // sanity: funds actually credited (admissible domain)
        assertTrue(c.getBalance(address(attacker)) == amount);

        // RULE: a funded re-entrant caller can always complete withdrawBalance,
        // because the balance is zeroed BEFORE the external call, so the re-entrant
        // getBalance sees 0. In the buggy version the re-entrant getBalance sees the
        // (still nonzero) balance and the attacker reverts, failing the withdrawal.
        bool ok = true;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "re-entrant withdrawal should not revert: balance must be zeroed before external call");
    }
}

contract Reentrant {
    C c;
    constructor(C _c) { c = _c; }

    function attack() external {
        c.withdrawBalance();
    }

    receive() external payable {
        // re-enter during the external call: in the correct contract the
        // balance has already been zeroed, so this must not revert.
        require(c.getBalance(address(this)) == 0, "balance not zeroed before external call");
    }
}
