pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor.code.length == 0);
        amount = bound(amount, 1, type(uint128).max);
        Observer obs = new Observer();
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        // withdraw via the observing helper as the caller
        vm.prank(address(obs));
        // give obs the actor's funds by using obs as the depositor instead
        vm.deal(address(obs), amount);
        vm.prank(actor);
        // revert the earlier actor deposit path: actor could only deposit own funds; redo cleanly
    }
}

contract Observer {
    C c;
    uint256 public seen;
    function run(C _c, uint256 amount) external {
        c = _c;
        (bool s,) = _c.call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        require(s, "deposit failed");
        _c.withdrawBalance();
    }
    receive() external payable {
        seen = c.getBalance(address(this));
    }
}

