        vm.prank(actor);
        try c.withdrawBalance() {
            // The contract's balance must have dropped by exactly the withdrawn amount.
            assertTrue(address(c).balance == before - amount);
        } catch {
            // If the withdrawal reverted, the contract must still hold everything.
            assertTrue(address(c).balance == before);
        }
    }
